create temp table late_project_revision as select revision,name,description from public.projects where id='f6300000-0000-4000-8000-000000000001';
grant select on late_project_revision to authenticated;
create function pg_temp.force_project_audit_failure() returns trigger language plpgsql as $$
begin
  if new.target_type='project' and new.target_id in ('f6300000-0000-4000-8000-000000000001'::uuid,'f6300000-0000-4000-8000-000000000999'::uuid) and new.event_type in ('project.created','project.updated') then
    raise exception using errcode='P0001',message='Fictional late project audit failure';
  end if;
  return new;
end;
$$;
create trigger fictional_project_audit_failure before insert on public.audit_logs for each row execute function pg_temp.force_project_audit_failure();
set local role authenticated; set local request.jwt.claims='{"sub":"f6100000-0000-4000-8000-000000000001","role":"authenticated"}';
select extensions.throws_ok('select public.create_organization_project(''f6200000-0000-4000-8000-000000000001'',''f6300000-0000-4000-8000-000000000999'',(select access_revision::bigint from public.organization_project_context(''f6200000-0000-4000-8000-000000000001'')),null,''{"name":"Atomic creation","description":"Audit failure rolls back"}'')','P0001',null,'Late audit failure aborts creation');
select extensions.is((select count(*)::integer from public.projects where id='f6300000-0000-4000-8000-000000000999'),0,'Late failure leaves no partial project');
select extensions.throws_ok('select public.update_organization_project(''f6200000-0000-4000-8000-000000000001'',''f6300000-0000-4000-8000-000000000001'',(select revision from late_project_revision),(select access_revision::bigint from public.organization_project_context(''f6200000-0000-4000-8000-000000000001'')),null,''{"name":"Atomic update","description":"Audit failure rolls back"}'')','P0001',null,'Late audit failure aborts edit');
select extensions.ok((select (revision,name,description)=(select revision,name,description from late_project_revision) from public.projects where id='f6300000-0000-4000-8000-000000000001'),'Late failure retains original content and revision');
reset role; drop trigger fictional_project_audit_failure on public.audit_logs;
select extensions.is((select count(*)::integer from public.audit_logs where target_id='f6300000-0000-4000-8000-000000000999'),0,'Late failure leaves no partial audit');
select * from extensions.finish(); rollback;
